## Add to types/api.ts:
Add these types at the end (before the ApiError interface or after it):
```typescript
export type ProjectStatus =
  | "Lead" | "Quote" | "Awarded" | "Design"
  | "Vendor" | "Execution" | "Validation" | "Closed";

export interface Client {
  id: string;
  name: string;
  code: string;
  address?: string;
  city?: string;
  state?: string;
  pincode?: string;
  country: string;
  gst_number?: string;
  primary_email: string;
  primary_phone?: string;
  notes?: string;
  is_active: boolean;
  created_at: string;
  updated_at: string;
  contacts: Contact[];
}

export interface Contact {
  id: string;
  client_id: string;
  name: string;
  email: string;
  phone?: string;
  designation?: string;
  is_primary: boolean;
}

export interface Project {
  id: string;
  client_id: string;
  name: string;
  code: string;
  description?: string;
  status: ProjectStatus;
  pm_id?: string;
  designer_id?: string;
  auditor_id?: string;
  location?: string;
  estimated_value?: number;
  actual_value?: number;
  start_date?: string;
  target_end_date?: string;
  actual_end_date?: string;
  is_active: boolean;
  created_at: string;
  updated_at: string;
  client_name?: string;
  pm_name?: string;
  designer_name?: string;
  auditor_name?: string;
}

export interface ClientListResponse {
  items: Client[];
  total: number;
  page: number;
  page_size: number;
}

export interface ProjectListResponse {
  items: Project[];
  total: number;
  page: number;
  page_size: number;
}
```

## Add API functions to lib/api.ts:
Add these functions after the existing API functions:
```typescript
export async function getClients(params: { page?: number; page_size?: number; search?: string } = {}): Promise<ClientListResponse> {
  const { page = 1, page_size = 20, search = "" } = params;
  const { data } = await axios.get<ClientListResponse>("/api/clients", {
    params: { page, page_size, search },
  });
  return data;
}

export async function getClient(id: string): Promise<Client> {
  const { data } = await axios.get<Client>(`/api/clients/${id}`);
  return data;
}

export async function createClient(payload: Partial<Client>): Promise<Client> {
  const { data } = await axios.post<Client>("/api/clients", payload);
  return data;
}

export async function updateClient(id: string, payload: Partial<Client>): Promise<Client> {
  const { data } = await axios.put<Client>(`/api/clients/${id}`, payload);
  return data;
}

export async function deleteContact(clientId: string, contactId: string): Promise<void> {
  await axios.delete(`/api/clients/${clientId}/contacts/${contactId}`);
}

export async function addContact(clientId: string, payload: Partial<Contact>): Promise<Contact> {
  const { data } = await axios.post<Contact>(`/api/clients/${clientId}/contacts`, payload);
  return data;
}

export async function getProjects(params: { page?: number; page_size?: number; search?: string; status?: string } = {}): Promise<ProjectListResponse> {
  const { page = 1, page_size = 20, search = "", status = "" } = params;
  const { data } = await axios.get<ProjectListResponse>("/api/projects", {
    params: { page, page_size, search, status },
  });
  return data;
}

export async function getProject(id: string): Promise<Project> {
  const { data } = await axios.get<Project>(`/api/projects/${id}`);
  return data;
}

export async function createProject(payload: Partial<Project>): Promise<Project> {
  const { data } = await axios.post<Project>("/api/projects", payload);
  return data;
}

export async function updateProject(id: string, payload: Partial<Project>): Promise<Project> {
  const { data } = await axios.put<Project>(`/api/projects/${id}`, payload);
  return data;
}

export async function transitionProject(id: string, status: ProjectStatus): Promise<Project> {
  const { data } = await axios.post<Project>(`/api/projects/${id}/transition`, { status });
  return data;
}

export async function getUsers(params: { role?: string } = {}): Promise<{ items: User[]; total: number }> {
  const { data } = await axios.get<{ items: User[]; total: number }>("/api/users", { params });
  return data;
}
```

## Create these files:

### src/components/clients/ClientList.tsx
A table component with search input (debounced 300ms), pagination, and list of clients.
```tsx
