            {client.notes && (
              <div>
                <Label className="text-muted-foreground">Notes</Label>
                <p className="text-sm">{client.notes}</p>
              </div>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex-row items-center justify-between">
            <CardTitle>Contacts</CardTitle>
            <Button size="sm" onClick={() => setShowAddContact(true)}>
              <Plus className="mr-2 h-4 w-4" />
              Add Contact
            </Button>
          </CardHeader>
          <CardContent>
            {showAddContact && (
              <div className="mb-4">
                <ContactForm
                  onSubmit={async (data) => {
                    await addContactMutation.mutateAsync(data);
                  }}
                  onCancel={() => setShowAddContact(false)}
                  isLoading={addContactMutation.isPending}
                />
              </div>
            )}
            {client.contacts.length === 0 ? (
              <p className="text-muted-foreground text-sm">No contacts yet</p>
            ) : (
              <div className="space-y-2">
                {client.contacts.map((contact) => (
                  <div key={contact.id} className="flex items-center justify-between border-b py-2">
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-medium">{contact.name}</span>
                        {contact.is_primary && (
                          <span className="text-xs bg-primary text-primary-foreground px-2 py-0.5 rounded">
                            Primary
                          </span>
                        )}
                      </div>
                      <div className="text-sm text-muted-foreground">
                        {contact.email} {contact.phone ? `· ${contact.phone}` : ""}
                        {contact.designation ? ` · ${contact.designation}` : ""}
                      </div>
                    </div>
                    <Button
                      size="icon"
                      variant="ghost"
                      onClick={() => deleteContactMutation.mutate(contact.id)}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

import { useNavigate } from "react-router-dom";
import { useMutation } from "@tanstack/react-query";
import { api } from "@/lib/api";
import { ClientForm } from "@/components/clients/ClientForm";
import { ArrowLeft } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Client } from "@/types/api";

export function NewClientPage() {
  const navigate = useNavigate();

  const mutation = useMutation({
    mutationFn: (data: Partial<Client>) => api.createClient(data),
    onSuccess: (client) => {
      navigate(`/clients/${client.id}`);
    },
  });

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="ghost" asChild>
          <a href="/clients">
            <ArrowLeft className="mr-2 h-4 w-4" />
            Back to Clients
          </a>
        </Button>
        <h1 className="text-2xl font-bold">New Client</h1>
      </div>

      <ClientForm
        onSubmit={async (data) => {
          await mutation.mutateAsync(data as any);
        }}
        onCancel={() => navigate("/clients")}
        isLoading={mutation.isPending}
      />
    </div>
  );
}

